$lead=lead_step20_get($pdo,$orgId,$id);$s=$pdo->prepare("SELECT a.*,u.full_name actor_name FROM crm_lead_activities a LEFT JOIN system_users u ON u.id=a.actor_user_id WHERE a.organization_id=? AND a.lead_id=? ORDER BY a.id DESC LIMIT 100");$s->execute([$orgId,$id]);$activities=$s->fetchAll();$s=$pdo->prepare("SELECT t.*,u.full_name assigned_name FROM crm_lead_tasks t LEFT JOIN system_users u ON u.id=t.assigned_user_id WHERE t.organization_id=? AND t.lead_id=? ORDER BY t.status='pending' DESC,t.due_at,t.id DESC");$s->execute([$orgId,$id]);$tasks=$s->fetchAll();$s=$pdo->prepare("SELECT a.*,u.full_name assigned_name FROM crm_appointments a LEFT JOIN system_users u ON u.id=a.assigned_user_id WHERE a.organization_id=? AND a.lead_id=? ORDER BY a.start_at DESC");$s->execute([$orgId,$id]);$appointments=$s->fetchAll();$s=$pdo->prepare("SELECT * FROM crm_lead_conversions WHERE organization_id=? AND lead_id=? ORDER BY id DESC");$s->execute([$orgId,$id]);$conversions=$s->fetchAll();$s=$pdo->prepare("SELECT u.id,u.full_name FROM system_users u JOIN organization_user_access a ON a.user_id=u.id AND a.organization_id=? WHERE u.is_active=1 AND a.is_active=1 ORDER BY u.full_name");$s->execute([$orgId]);$users=$s->fetchAll();$mobile=lead_step20_normalize_mobile((string)$lead['mobile']);$email=lead_step20_normalize_email((string)$lead['email']);$clauses=[];$args=[$orgId];if($mobile!==''){$clauses[]="REPLACE(REPLACE(REPLACE(COALESCE(mobile,''),'+',''),' ',''),'-','') LIKE ?";$args[]='%'.$mobile;}if($email!==''){$clauses[]="LOWER(COALESCE(email,''))=?";$args[]=$email;}if($clauses){$s=$pdo->prepare("SELECT id,customer_code,customer_name,mobile,email FROM crm_customers WHERE organization_id=? AND status='active' AND (".implode(' OR ',$clauses).") ORDER BY id DESC LIMIT 10");$s->execute($args);$customers=$s->fetchAll();}$s=$pdo->prepare("SELECT id,full_name,mobile FROM members WHERE organization_id=? AND COALESCE(source_sheet,'')<>? AND (full_name LIKE ? OR COALESCE(mobile,'') LIKE ?) ORDER