?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Lead 360 - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/step10.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="lead_center.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 20 • Lead 360°</small></span></a><div class="os-top-actions"><a class="os-btn" href="lead_center.php">Leads</a><a class="os-btn primary" href="index.php">Dashboard</a></div></div></header><main class="os-main" style="max-width:1500px;margin:auto"><?php if($error):?><div class="pp-alert bad"><?= lead_step20_h($error) ?></div><?php elseif($lead):?><section class="os-hero pp-hero"><div class="os-kicker"><?= lead_step20_h($lead['lead_code']) ?> • <?= lead_step20_h(strtoupper($lead['lead_type'])) ?></div><h1><?= lead_step20_h($lead['full_name']) ?></h1><p><?= lead_step20_h($lead['message']?:'No message supplied.') ?></p><div class="os-status-row"><span class="os-chip good"><?= lead_step20_h(strtoupper($lead['stage'])) ?></span><span class="os-chip"><?= lead_step20_h(strtoupper($lead['priority'])) ?></span><span class="os-chip"><?= (int)$lead['submission_count'] ?> submission(s)</span><span class="os-chip"><?= lead_step20_h($lead['source_name']?:'Unknown source') ?></span></div><div class="os-links" style="margin-top:14px"><a class="os-btn" href="tel:<?= lead_step20_h($lead['mobile']) ?>">Call</a><a class="os-btn" href="<?= lead_step20_h($wa) ?>" target="_blank" rel="noopener">WhatsApp</a><?php if($lead['email']):?><a class="os-btn" href="mailto:<?= lead_step20_h($lead['email']) ?>">Email</a><?php endif;?></div></section><?php if($success):?><div class="pp-alert good"><?= lead_step20_h($success) ?></div><?php endif;?><section class="s10-grid"><article class="s10-card s10-span-6"><h2>Lead Control</h2><form method="post"><input type="hidden" name="csrf" value="<?= lead_step20_h(security_step17_csrf()) ?>"><input type="hidden" name="id" value="<?= $id ?>"><input type="hidden" name="action" value="stage"><label><b>Stage</b><select name="stage" style="width:100%;margin:6px 0 10px"><?php foreach(lead_step20_stages() as $st):?><option value="<?= $st ?>" <?= $lead['stage']===$st?'selected':'' ?>><?= lead_step20_h(ucwords($st)) ?></option><?php endforeach;?></select></label><label><b>Priority</b><select name="priority" style="width:100%;margin:6px 0 10px"><?php foreach(lead_step20_priorities() as $p):?><option value="<?= $p ?>" <?= $lead['priority']===$p?'selected':'' ?>><?= lead_step20_h(ucwords($p)) ?></option><?php endforeach;?></select></label><label><b>Note</b><textarea name="notes" rows="2" style="width:100%;margin-top:6px"></textarea></label><button class="os-btn primary" style="margin-top:10px">Update Stage</button></form><hr><form method="post"><input type="hidden" name="csrf" value="<?= lead_step20_h(security_step17_csrf()) ?>"><input type="hidden" name="id" value="<?= $id ?>"><input type="hidden" name="action" value="assign"><label><b>Assigned to</b><select name="assigned_user_id" style="width:100%;margin:6px 0 10px"><option value="0">Unassigned</option><?php foreach($users as $u):?><option value="<?= (int)$u['id'] ?>" <?= (int)$lead['assigned_user_id']===(int)$u['id']?'selected':'' ?>><?= lead_step20_h($u['full_name']) ?></option><?php endforeach;?></select></label><button class="os-btn">Save Assignment</button></form></article><article class="s10-card s10-span-6"><h2>Contact & Source</h2><div class="s10-list"><div class="s10-row"><div><b>Mobile</b><small><?= lead_step20_h($lead['mobile']?:'—') ?></small></div></div><div class="s10-row"><div><b>Email</b><small><?= lead_step20_h($lead['email']?:'—') ?></small></div></div><div class="s10-row"><div><b>Requested Appointment</b><small><?= lead_step20_h($lead['requested_appointment_at']?:'Not requested') ?></small></div></div><div class="s10-row"><div><b>First / Last seen</b><small><?= lead_step20_h($lead['first_seen_at'].' / '.$lead['last_seen_at']) ?></small></div></div></div></article><article class="s10-card s10-span-6"><h2>Add Follow-up</h2><form method="post"><input type="hidden" name="csrf" value="<?= lead_step20_h(security_step17_csrf()) ?>"><input type="hidden" name="id" value="<?= $id ?>"><input type="hidden" name="action" value="task"><select name="task_type" style="width:100%;margin-bottom:10px"><?php foreach(['call','whatsapp','visit','email','note'] as $t):?><option value="<?= $t ?>"><?= ucfirst($t) ?></option><?php endforeach;?></select><input name="subject" required placeholder="Follow-up subject" style="width:100%;margin-bottom:10px"><input type="datetime-local" name="due_at" required style="width:100%;margin-bottom:10px"><select name="assigned_user_id" style="width:100%;margin-bottom:10px"><option value="0">No assignee</option><?php foreach($users as $u):?><option value="<?= (int)$u['id'] ?>"><?= lead_step20_h($u['full_name']) ?></option><?php endforeach;?></select><textarea name="notes" rows="2" placeholder="Notes" style="width:100%"></textarea><button class="os-btn primary" style="margin-top:10px">Create Follow-up</button></form></article><article class="s10-card s10-span-6"><h2>Schedule Appointment</h2><form method="post"><input type="hidden" name="csrf" value="<?= lead_step20_h(security_step17_csrf()) ?>"><input type="hidden" name="id" value="<?= $id ?>"><input type="hidden" name="action" value="appointment"><input type="datetime-local" name="start_at" required style="width:100%;margin-bottom:10px"><select name="mode" style="width:100%;margin-bottom:10px"><option value="club">Club visit</option><option value="phone">Phone</option><option value="video">Video</option><option value="home">Home visit</option></select><input name="purpose" placeholder="Purpose" style="width:100%;margin-bottom:10px"><select name="assigned_user_id" style="width:100%;margin-bottom:10px"><option value="0">No assignee</option><?php foreach($users as $u):?><option value="<?= (int)$u['id'] ?>"><?= lead_step20_h($u['full_name']) ?></option><?php endforeach;?></select><textarea name="notes" rows="2" placeholder="Notes" style="width:100%"></textarea><button class="os-btn primary" style="margin-top:10px">Schedule</button></form></article><article class="s10-card s10-span-6"><h2>Convert to Customer</h2><?php if($customers):?><div class="pp-alert">Matching customer(s) exist. Link explicitly to avoid duplicates.</div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?= lead_step20_h(security_step17_csrf()) ?>"><input type="hidden" name="id" value="<?= $id ?>"><input type="hidden" name="action" value="customer"><label><b>Existing Customer (optional)</b><select name="customer_id" style="width:100%;margin:6px 0 10px"><option value="0">Create new customer only if no match exists</option><?php foreach($customers as $c):?><option value="<?= (int)$c['id'] ?>">#<?= (int)$c['id'] ?> <?= lead_step20_h($c['customer_name'].' • '.$c['mobile']) ?></option><?php endforeach;?></select></label><textarea name="notes" rows="2" placeholder="Conversion note" style="width:100%"></textarea><button class="os-btn primary" style="margin-top:10px">Convert / Link Customer</button></form></article><article class="s10-card s10-span-6"><h2>Link Existing Member</h2><p>Member creation stays in the verified Member/Data Entry workflow. Enter/select an existing Member only.</p><form method="post"><input type="hidden" name="csrf" value="<?= lead_step20_h(security_step17_csrf()) ?>"><input type="hidden" name="id" value="<?= $id ?>"><input type="hidden" name="action" value="member"><select name="member_id" required style="width:100%;margin-bottom:10px"><option value="">Choose member</option><?php foreach($members as $m):?><option value="<?= (int)$m['id'] ?>">#<?= (int)$m['id'] ?> <?= lead_step20_h($m['full_name'].' • '.$m['mobile']) ?></option><?php endforeach;?></select><textarea name="notes" rows="2" placeholder="Conversion note" style="width:100%"></textarea><button class="os-btn">Link Member</button></form></article></section><section class="s10-grid" style="margin-top:14px"><article class="s10-card s10-span-6"><h2>Follow-ups</h2><div class="s10-list"><?php if(!$tasks):?><div class="pp-alert">No follow-ups yet.</div><?php endif;?><?php foreach($tasks as $t):?><div class="s10-row"><div><b><?= lead_step20_h(strtoupper($t['task_type']).' • '.$t['subject']) ?></b><small><?= lead_step20_h($t['due_at'].' • '.$t['status'].($t['assigned_name']?' • '.$t['assigned_name']:'')) ?></small></div></div><?php endforeach;?></div></article><article class="s10-card s10-span-6"><h2>Appointments</h2><div class="s10-list"><?php if(!$appointments):?><div class="pp-alert">No appointments yet.</div><?php endif;?><?php foreach($appointments as $a):?><div class="s10-row"><div><b><?= lead_step20_h($a['appointment_code'].' • '.strtoupper($a['status'])) ?></b><small><?= lead_step20_h($a['start_at'].' • '.$a['appointment_mode']) ?></small></div></div><?php endforeach;?></div></article><article class="s10-card s10-span-12"><h2>Activity Timeline</h2><div class="s10-list"><?php foreach($activities as $a):?><div class="s10-row"><div><b><?= lead_step20_h($a['subject']?:$a['activity_type']) ?></b><small><?= lead_step20_h($a['created_at'].($a['actor_name']?' • '.$a['actor_name']:'')) ?></small><?php if($a['notes']):?><small><?= lead_step20_h($a['notes']) ?></small><?php endif;?></div></div><?php endforeach;?></div></article></section><?php endif;?></main></body></html>